import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { chromium } from "@playwright/test";
import { iconBrowserOptions } from "./icon-browser.mjs";

// Verification mode compares every generated byte without rewriting public files.
async function emit(file, data) {
  const bytes = Buffer.from(data);
  if (process.argv.includes("--check")) {
    if (!(await readFile(file)).equals(bytes)) throw new Error(`Icon needs regeneration: ${file}`);
  } else {
    await writeFile(file, bytes);
  }
}

// Keep the original brand geometry; never redraw the symbol by hand.
// Source of truth: public/logo.svg (the header/landing logo). Every icon below
// is derived from its 48×48 mark so the brand stays identical everywhere.
const publicDir = resolve(import.meta.dirname, "../public");
const logo = await readFile(resolve(publicDir, "logo.svg"), "utf8");
const rect = logo.match(/<rect\b[^>]*\/>/)?.[0];
const paths = [...logo.matchAll(/<path\b[^>]*\/>/g)].slice(0, 2).map(([path]) => path);
const circle = logo.match(/<circle\b[^>]*\/>/)?.[0];
if (!rect || paths.length !== 2 || !circle) throw new Error("Original logo symbol not found");
const symbol = [rect, ...paths, circle].join("\n");

/** Dark full-bleed finish for platforms that flatten alpha or apply a mask. */
function opaque(padding = 0) {
  const scale = (512 - padding * 2) / 48;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512">
<rect width="512" height="512" fill="#1A1A1A"/>
<g transform="translate(${padding} ${padding}) scale(${scale}) translate(-3 -3)">
${symbol}
</g>
</svg>\n`;
}
/** The bare mark cropped to its black rounded outline, transparent outside it. */
const mark = `<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="3 3 48 48" fill="none">\n${symbol}\n</svg>\n`;

const standard = mark;
await emit(resolve(publicDir, "icons/icon-source.svg"), standard);
const favicon = mark;
await emit(resolve(publicDir, "favicon.svg"), favicon);
// Bare symbol for in-app UI such as the install bar.
await emit(resolve(publicDir, "logo-mark.svg"), mark);

const browser = await chromium.launch({
  headless: true,
  ...iconBrowserOptions(),
});
try {
  const page = await browser.newPage();
  const render = (source, size) => page.evaluate(async ({ source, size }) => {
    const image = new Image();
    image.src = `data:image/svg+xml;base64,${btoa(source)}`;
    await image.decode();
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(image, 0, 0, size, size);
    return canvas.toDataURL("image/png").split(",")[1];
  }, { source, size }).then((b64) => Buffer.from(b64, "base64"));

  const outputs = [
    [resolve(publicDir, "icons/favicon-32.png"), favicon, 32],
    // New canonical URLs; keep historical aliases visually consistent as well.
    [resolve(publicDir, "favicon.png"), favicon, 96],
    [resolve(publicDir, "favicon-outline.svg"), favicon, null],
    [resolve(publicDir, "favicon-outline.png"), favicon, 96],
    [resolve(publicDir, "icons/receebo-outline-180.png"), opaque(), 180],
    [resolve(publicDir, "icons/receebo-outline-192.png"), standard, 192],
    [resolve(publicDir, "icons/receebo-outline-512.png"), standard, 512],
    [resolve(publicDir, "icons/receebo-outline-maskable-512.png"), opaque(112), 512],
    [resolve(publicDir, "icons/receebo-app-180.png"), opaque(), 180],
    [resolve(publicDir, "icons/receebo-app-192.png"), standard, 192],
    [resolve(publicDir, "icons/receebo-app-512.png"), standard, 512],
    [resolve(publicDir, "icons/receebo-app-maskable-512.png"), opaque(112), 512],
    [resolve(publicDir, "icons/receebo-white-32.png"), favicon, 32],
    [resolve(publicDir, "icons/receebo-white-180.png"), opaque(), 180],
    [resolve(publicDir, "icons/receebo-white-192.png"), standard, 192],
    [resolve(publicDir, "icons/receebo-white-512.png"), standard, 512],
    // The symbol fits entirely inside the maskable icon's central safe circle.
    [resolve(publicDir, "icons/receebo-white-maskable-512.png"), opaque(112), 512],
    // Legacy names kept for devices that cached the pre-Receebo manifest.
    [resolve(publicDir, "icons/icon-192.png"), standard, 192],
    [resolve(publicDir, "icons/icon-512.png"), standard, 512],
    [resolve(publicDir, "icons/icon-512-maskable.png"), opaque(112), 512],
    // Common legacy Apple fallback, even when HTML metadata isn't consulted.
    [resolve(publicDir, "apple-touch-icon.png"), opaque(), 180],
  ];
  for (const [file, source, size] of outputs) {
    await emit(file, size ? await render(source, size) : source);
    console.log(`Generated ${file.replace(resolve(publicDir, "../.."), "")} (${size ? `${size}×${size}` : "SVG"})`);
  }
  // Expo and monochrome notification badges are intentionally not generated here.

  // favicon.ico (16/32/48) with embedded PNGs, for browsers that ask for /favicon.ico.
  const sizes = [16, 32, 48];
  const pngs = [];
  for (const size of sizes) pngs.push(await render(favicon, size));
  const header = Buffer.alloc(6 + 16 * sizes.length);
  header.writeUInt16LE(0, 0); header.writeUInt16LE(1, 2); header.writeUInt16LE(sizes.length, 4);
  let offset = header.length;
  sizes.forEach((size, i) => {
    const entry = 6 + i * 16;
    header.writeUInt8(size, entry); header.writeUInt8(size, entry + 1);
    header.writeUInt16LE(1, entry + 4); header.writeUInt16LE(32, entry + 6);
    header.writeUInt32LE(pngs[i].length, entry + 8); header.writeUInt32LE(offset, entry + 12);
    offset += pngs[i].length;
  });
  await emit(resolve(publicDir, "favicon.ico"), Buffer.concat([header, ...pngs]));
  await emit(resolve(publicDir, "favicon-outline.ico"), Buffer.concat([header, ...pngs]));
  console.log("Generated favicon.ico (16/32/48)");
} finally {
  await browser.close();
}
